    offlineDB.init()
      .then(() => {
        if (isMounted) {
          loadData().finally(() => {
            if (isMounted) setIsLoading(false);
          });
        }
      })
      .catch((err) => {
        console.warn('DB init note:', err);
        if (isMounted) setIsLoading(false);
      });

    const unsub = offlineDB.subscribe(() => {
      if (isMounted) loadData();
    });

    return () => {
      isMounted = false;
      clearTimeout(safetyTimer);
      unsub();
    };
